const params = $('Parse RSVP Output').first().json.output.parameters;

const data = {
  _id: $('Find Appointment').first().json._id.toString().replace(/^"(.*)"$/, '$1'),
  updated_at: $now.toISO()
};

if (params.tipo_agendamiento && params.tipo_agendamiento !== 'null') data.tipo = params.tipo_agendamiento;
if (params.fecha_hora && params.fecha_hora !== 'null') data.fecha_hora = params.fecha_hora;
if (params.horario_preferido && params.horario_preferido !== 'null') data.horario_preferido = params.horario_preferido;
if (params.medio_llamada && params.medio_llamada !== 'null') data.medio_llamada = params.medio_llamada;
if (params.cita_confirmada) data.confirmada = params.cita_confirmada;

return [{ json: data }];

const params = $('Parse RSVP Output').first().json.output.parameters;
const ctx = $('CONTEXT').item.json;

const data = {
  contactId: ctx.contactId,
  dealer: ctx.dealer,
  nombre: ctx.nombre,
  vehiculo_interes: ctx.vehiculo_interes,
  created_at: $now.toISO(),
  updated_at: $now.toISO()
};

if (params.tipo_agendamiento && params.tipo_agendamiento !== 'null') data.tipo = params.tipo_agendamiento;
if (params.fecha_hora && params.fecha_hora !== 'null') data.fecha_hora = params.fecha_hora;
if (params.horario_preferido && params.horario_preferido !== 'null') data.horario_preferido = params.horario_preferido;
if (params.medio_llamada && params.medio_llamada !== 'null') data.medio_llamada = params.medio_llamada;
if (params.cita_confirmada) data.confirmada = params.cita_confirmada;

return [{ json: data }];

const ctx = $('CONTEXT').item.json;
const params = $('Parse RSVP Output').item.json.output.parameters;

const tipoLabel = {
  'cita_presencial': 'Visita presencial al concesionario',
  'cita_virtual': 'Videollamada con un asesor',
  'llamada': 'Llamada telefónica'
}[params.tipo_agendamiento] || '-';

const fechaIso = params.fecha_hora || $('Find Appointment').first().json.fecha_hora;
let fecha = '-';
if (fechaIso) {
  const dt = DateTime.fromISO(fechaIso, { zone: 'America/New_York' });
  if (dt.isValid) {
    const txt = dt.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a");
    fecha = (txt.charAt(0).toUpperCase() + txt.slice(1)) + ' (hora Miami)';
  }
}
const medioLlamadaLabel = params.medio_llamada === 'whatsapp' ? 'WhatsApp' : params.medio_llamada === 'telefono' ? 'Teléfono' : '-';

return [{ json: {
  fecha,
  modalidad: tipoLabel,
  tipo_agendamiento: params.tipo_agendamiento || null,
  horario_preferido: params.horario_preferido || null,
  medio_llamada: params.medio_llamada || null,
  medio_llamada_label: medioLlamadaLabel
} }];

const raw = $input.first().json.output || '';

function extractJSON(text) {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch(e) { return null; }
}

const parsed = extractJSON(raw);

if (!parsed) {
  return [{
    json: {
      output: {
        response: raw,
        parameters: {
          tipo_agendamiento: null,
          horario_preferido: null,
          medio_llamada: null,
          fecha_hora: null,
          cita_confirmada: false
        }
      }
    }
  }];
}

const p = parsed.parameters || {};
const norm = (v) => (v === 'null' || v === '' || v === undefined) ? null : v;

return [{
  json: {
    output: {
      response: parsed.response || raw,
      parameters: {
        tipo_agendamiento: norm(p.tipo_agendamiento),
        horario_preferido: norm(p.horario_preferido),
        medio_llamada: (() => { const v = norm(p.medio_llamada); if (!v) return null; const s = String(v).toLowerCase().replace(/[^a-z]/g, ''); if (s.includes('whats')) return 'whatsapp'; if (s.includes('telef') || s.includes('phone') || s === 'tel') return 'telefono'; return s === 'telefono' || s === 'whatsapp' ? s : null; })(),
        fecha_hora: (() => {
          const rawFecha = norm(p.fecha_hora);
          if (rawFecha) {
            const local = rawFecha.replace(/(\.[0-9]+)?(Z|[+-]\d{2}:?\d{2})$/, '');
            const dt = DateTime.fromISO(local, { zone: 'America/New_York' });
            return dt.isValid ? dt.toISO({ suppressMilliseconds: true }) : null;
          }
          if (norm(p.tipo_agendamiento) === 'llamada' && norm(p.horario_preferido)) {
            const horario = p.horario_preferido.toLowerCase().trim();
            let hour = null, minute = 0;

            const despuesM = horario.match(/(?:despu[ee]s\s+de\s+las?|a\s+partir\s+de\s+las?)\s+(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?/);
            const rangoM = !despuesM && horario.match(/de\s+las?\s+(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?/);
            const horaM = !despuesM && !rangoM && horario.match(/\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.)\b/);
            const hora24M = !despuesM && !rangoM && !horaM && horario.match(/\b(\d{1,2}):(\d{2})\b/);

            const matchUsado = despuesM || rangoM || horaM || hora24M;

            if (matchUsado) {
              hour = parseInt(matchUsado[1]);
              minute = matchUsado[2] ? parseInt(matchUsado[2]) : 0;
              const ampm = ((matchUsado[3] || '').replace(/[.\s]/g, '')).toLowerCase();
              if (ampm === 'pm' && hour < 12) hour += 12;
              else if (ampm === 'am' && hour === 12) hour = 0;
            } else if (/mediod[ii]a|medio\s+d[ii]a/.test(horario)) {
              hour = 12; minute = 0;
            } else if (/\btarde\b/.test(horario)) {
              hour = 14; minute = 0;
            } else if (/\bnoche\b/.test(horario)) {
              hour = 19; minute = 0;
            } else if (/\bma[nn]ana\b/.test(horario)) {
              hour = 9; minute = 0;
            } else if (/ahorita|ahora|\bya\b/.test(horario)) {
              const et = $now.setZone('America/New_York');
              const dt = et.plus({ hours: 1 }).set({ minute: 0, second: 0, millisecond: 0 });
              return dt.toISO({ suppressMilliseconds: true });
            }

            if (hour !== null) {
              const et = $now.setZone('America/New_York');
              let dt = et.set({ hour, minute, second: 0, millisecond: 0 });
              if (dt <= et) dt = dt.plus({ days: 1 });
              return dt.toISO({ suppressMilliseconds: true });
            }
          }
          return null;
        })(),
        cita_confirmada: p.cita_confirmada === true
      }
    }
  }
}];
